local MainHomeScrollEntryNode = Class('MainHomeScrollEntryNode')

function MainHomeScrollEntryNode:__init()
    self._allData = {}
    self._behaviourAction = nil 
    self._targetTime = 3         --循环时间
    self._curTime = 0
    self._isLoop = false
    self._curInd = 0
    self._maxInd = 0
end

function MainHomeScrollEntryNode:__delete()
    self._allData = nil
    self._behaviourAction = nil 
    self._targetTime = nil         --循环时间
    self._curTime = nil
    self._isLoop = false
end

function MainHomeScrollEntryNode:Start()
    self.EventMainHomeScrollActive = Events.AddListener(Constants.EventNames.MainHomeScrollActive, Bind(self, self.OnEventMainHomeScrollActive))
    self.EventMainHomeUpdateTVShow = Events.AddListener(Constants.EventNames.MainHomeTVPlayerVisibleUpdate, function(visible)
        KTool.SetActive(self.MusicPlayerScreenCanvas, checkBool(visible))
    end)
    self.EventMainHomeUpdateCDList = Events.AddListener(Constants.EventNames.MainHomeUpdateCDList, Bind(self, self.OnUpdateCDList))


    self._behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    self._behaviourAction.UpdateAction = function()
        self:OnUpdate()
    end

    self._behaviourAction.OnEnableAction = function()
        self._curTime = 0
        self._curInd = 1
        self:RereshImage()
    end
    
    local quickTap = KTool.GetOrAddComponent(self.BtnClick.gameObject, typeof(CS.HedgehogTeam.EasyTouch.QuickTap))
    if not isNull(quickTap) then
        quickTap.onTap:RemoveAllListeners()
        quickTap.onTap:AddListener(Bind(self, self.OnClick))
    end

    self._materialProperty = CS.UnityEngine.MaterialPropertyBlock()
    self._textureId = CS.UnityEngine.Shader.PropertyToID("_MainTex");
    self.bg_sh_television_screen:GetPropertyBlock(self._materialProperty)

    self:InitData()
end

function MainHomeScrollEntryNode:OnEventMainHomeScrollActive(body)
    if not body then
        return
    end
    KTool.SetActive(self.controller.gameObject, checkBool(body.isTrue))
end

function MainHomeScrollEntryNode:OnUpdateCDList(data)
    local cdData     = data.data
    local isNeedAnim = checkBool(data.needAnim)
    local length = math.max(#cdData, #checkTable(self.cdListId))
    for index = 1, length do
        local preId = checkInt(checkTable(self.cdListId)[index])
        local curId = checkInt(cdData[index])
        if preId ~= curId then
            local node = self.MusicList.transform:Find("MusicNameNode"..index)
            if not node then
                if index == 1 then
                    node = self.MusicNameNode
                else
                    node = CfUtils.InstantiateGo(self.MusicNameNode, self.MusicList)
                end
                if node then
                    node.name = "MusicNameNode" .. index
                end
            end

            if curId > 0 then
                local numberNode = node.transform:Find("TxtNumber")
                local nameNode   = node.transform:Find("TxtName")
                ---@type MusicPlayerVo
                local musicVo = CfUtils.GetCfVo(AutoIds.IdSetting899, "MusicPlayerVo", curId)
                if musicVo == nil or next(musicVo) == nil then
                    musicVo = CfUtils.GetCfVo(AutoIds.IdSetting899, "MusicPlayerVo", PlayerInfoUtils.GetDefaultMusicId())
                end
                CfUtils.FillText(numberNode, string.format("%.2d", index))
                CfUtils.FillText(nameNode, musicVo.name)

            end
            KTool.SetActive(node, curId > 0)
            if not isNeedAnim then
                local animation = node.transform:GetComponent(typeof(CS.UnityEngine.Animation))
                if animation then
                    animation:Play("UIMusicPlayerScreenCanvasMusicNodeIdle")
                end
            end
        end
    end
    self.cdListId = clone(cdData)
    CfUtils.FillText(self.TxtNumber, string.format("%s/%s", #cdData, PlayerInfoUtils.GetMaxCDSetNum()))

    if isNeedAnim then
        cs_coroutine.start(function()
            for index = 1, length do
                local node = self.MusicList.transform:Find("MusicNameNode"..index)
                local animation = node.transform:GetComponent(typeof(CS.UnityEngine.Animation))
                if animation then
                    animation:Play("UIMusicPlayerScreenCanvasMusicNodeIn")
                end
                coroutine.yield(WaitForSeconds(0.1))
            end
        end)
    end
end

--点击
function MainHomeScrollEntryNode:OnClick()
    --引导中  退出
    if GuideUtils.IsInGuiding() then return end

    --如果不在主界面  退出
    if checkNumber(KCookie.Get("IsInUIHomeMain")) == 0 then
        return
    elseif not self._allData then
        return
    end

    --主界面没显示不让点
    if checkNumber(KCookie.Get("IsNotUIHomeMainShow")) == 1 then
        return
    end

    local data = self._allData[self._curInd]
    if not data then
        return
    end
    if checkNumber(data.moduleId) == 0 then
        return
    end

    self:__ExecuteJump(data.moduleId, data.param)
end

function MainHomeScrollEntryNode:__ExecuteJump(moduleId, param)
    local blocker = CS.Engine.UI.UIRaycastBlocker.Instance
    blocker:AddCondition("__ExecuteJump")
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    xTry(function ()
        cs_coroutine.start(function ()
            Events.Broadcast(Constants.EventNames.MainHomeRoleActive, {isShow = false})
            --[[
            local isShow = false
            GameUtils.ShowBlackOverlay(nil, function()
                while not isShow do
                    coroutine.yield(Yielders.EndOfFrame)
                end
            end)
            coroutine.yield(WaitForSeconds(0.5))
            ]]

            local row = goodsConfMgr:GetJumpModuleRow(moduleId)
            if row then
                cs_coroutine.yield_return(goodsConfMgr:ExecuteJump(row, {}, 0, nil, param))
            end
            --coroutine.yield(WaitForSeconds(5))
            --isShow = true
            blocker:RemoveCondition("__ExecuteJump")
        end)
    end, function()
        print_to_file(debug.traceback())
        blocker:RemoveCondition("__ExecuteJump")
    end)
end

function MainHomeScrollEntryNode:InitData()
    self._allData = comp:GetData()
    if not self._allData or table.count(self._allData) < 1 then
        return
    end
    self._curTime = self._targetTime
    self._curInd = 0
    self._maxInd = table.count(self._allData)

    self._isLoop = true
end

function MainHomeScrollEntryNode:OnUpdate()
    if not self._isLoop then
        return
    end
    if self._curTime >= self._targetTime then
        self._curTime = 0
        self._curInd = self._curInd + 1
        if self._curInd > self._maxInd then
            self._curInd = 1
        end

        self:RereshImage()
    else
        self._curTime = self._curTime + CS.UnityEngine.Time.deltaTime
    end
end

function MainHomeScrollEntryNode:RereshImage()
    if self._co then
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    local data = self._allData[self._curInd]
    if not data then
        return
    end

    self._co = cs_coroutine.start(function()
        --local spr = CfUtils.GetWWWSprite("https://img.fantanggame.com/cat-phone/79510801a77803b9b5fb1a0ec000d2a2.png")
        if isNull(data.image) then
            return
        else
            local strs = CfUtils.Split(data.image)
            if strs then
                local num1, num2 = string.find(data.image, ".png")
                if checkNumber(num1) == 0 then
                    GameUtils.Toast(localize("主界面轮播图不是png格式"))
                    return
                end
            end
        end

        local spr = CfUtils.GetWWWSprite(data.image)
        if spr then


            self._materialProperty:SetTexture(self._textureId, spr)
            self.bg_sh_television_screen:SetPropertyBlock(self._materialProperty);

            --self.ScrollNode.sprite = spr
        end
    end)
end

function MainHomeScrollEntryNode:OnDestroy()
    Events.RemoveListener(Constants.EventNames.MainHomeScrollActive, self.EventMainHomeScrollActive)
    Events.RemoveListener(Constants.EventNames.MainHomeTVPlayerVisibleUpdate, self.EventMainHomeUpdateTVShow)
    Events.RemoveListener(Constants.EventNames.MainHomeUpdateCDList, self.EventMainHomeUpdateCDList)

    if not isNull(self._behaviourAction) then
        self._behaviourAction.UpdateAction = nil
    end
    if self._co then
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return MainHomeScrollEntryNode